  <!-- ═══ SECTION 1 — TIMELINE CHART ═══ -->
  <div class="timeline-section">
    <div class="section-label">
      <div class="section-num">1</div>
      <h2>The Long Arc of Book Production · <em>6th Century → Present</em></h2>
    </div>
    <div class="chart-wrap">
      <svg class="timeline-svg-wrap" viewBox="0 0 714 220" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="manuGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#b8860b" stop-opacity="0.55"/>
            <stop offset="100%" stop-color="#b8860b" stop-opacity="0.05"/>
          </linearGradient>
          <linearGradient id="printGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#c0522a" stop-opacity="0.75"/>
            <stop offset="100%" stop-color="#c0522a" stop-opacity="0.05"/>
          </linearGradient>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
            <feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge>
          </filter>
        </defs>

        <!-- Grid lines -->
        <line x1="60" y1="20" x2="60" y2="175" stroke="#e0d0bb" stroke-width="0.5"/>
        <line x1="60" y1="55" x2="700" y2="55" stroke="#e0d0bb" stroke-width="0.5" stroke-dasharray="3,3"/>
        <line x1="60" y1="90" x2="700" y2="90" stroke="#e0d0bb" stroke-width="0.5" stroke-dasharray="3,3"/>
        <line x1="60" y1="125" x2="700" y2="125" stroke="#e0d0bb" stroke-width="0.5" stroke-dasharray="3,3"/>
        <line x1="60" y1="160" x2="700" y2="160" stroke="#e0d0bb" stroke-width="0.5" stroke-dasharray="3,3"/>

        <!-- Y-axis labels -->
        <text x="54" y="58" text-anchor="end" font-size="7" fill="#7a6250">High</text>
        <text x="54" y="93" text-anchor="end" font-size="7" fill="#7a6250">Med</text>
        <text x="54" y="128" text-anchor="end" font-size="7" fill="#7a6250">Low</text>
        <text x="54" y="163" text-anchor="end" font-size="7" fill="#7a6250">Minimal</text>
        <text x="54" y="178" text-anchor="end" font-size="7" fill="#7a6250">0</text>

        <!--
          X-axis spans: 500 CE → 2025 CE = 1525 years
          Chart area: x=60 to x=700, width=640
