        <!-- X-axis baseline -->
        <line x1="60" y1="175" x2="700" y2="175" stroke="#5c3d20" stroke-width="1"/>

        <!-- X-axis labels -->
        <text x="60"  y="186" text-anchor="middle" font-size="7.5" fill="#5c3d20">500</text>
        <text x="270" y="186" text-anchor="middle" font-size="7.5" fill="#5c3d20">1000</text>
        <text x="480" y="186" text-anchor="middle" font-size="7.5" fill="#5c3d20">1500</text>
        <text x="564" y="186" text-anchor="middle" font-size="7.5" fill="#5c3d20">1700</text>
        <text x="648" y="186" text-anchor="middle" font-size="7.5" fill="#5c3d20">1900</text>
