        <rect x="62" y="198" width="10" height="8" rx="1" fill="#b8860b" opacity="0.6"/>
        <text x="76" y="206" font-size="8" fill="#5c3d20">Manuscripts (Europe)</text>
        <rect x="175" y="198" width="10" height="8" rx="1" fill="#c0522a" opacity="0.7"/>
        <text x="189" y="206" font-size="8" fill="#5c3d20">Printed Books (Global)</text>
