<script>
async function exportPNG() {
  const btn = document.getElementById('export-btn');
  btn.textContent = 'Generating…';
  btn.disabled = true;

  try {
    // Use html2canvas approach via a canvas element
    const poster = document.getElementById('poster');
    const w = poster.scrollWidth;
    const h = poster.scrollHeight;

    // Inline SVG data-URLs for fonts (if needed) — use canvas
    const canvas = document.createElement('canvas');
    const scale = 2; // 2× for retina quality
    canvas.width  = w * scale;
    canvas.height = h * scale;
    const ctx = canvas.getContext('2d');
    ctx.scale(scale, scale);

    // Serialize the poster to SVG via foreignObject
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('xmlns', svgNS);
    svg.setAttribute('width', w);
    svg.setAttribute('height', h);

    const fo = document.createElementNS(svgNS, 'foreignObject');
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);

    const htmlClone = poster.cloneNode(true);
    // Hide export button in clone
    const cloneBtn = htmlClone.querySelector('#export-btn');
    if (cloneBtn) cloneBtn.style.display = 'none';

    // Inline computed styles
    const wrapper = document.createElement('div');
    wrapper.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
    wrapper.style.cssText = `width:${w}px;background:#f5ede0;`;
    wrapper.appendChild(htmlClone);
    fo.appendChild(wrapper);
    svg.appendChild(fo);

    const svgStr = new XMLSerializer().serializeToString(svg);
    const svgBlob = new Blob([svgStr], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();
    img.onload = () => {
      ctx.drawImage(img, 0, 0);
      URL.revokeObjectURL(url);
      const pngUrl = canvas.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = pngUrl;
      a.download = 'books-history-poster.png';
      a.click();
      btn.textContent = 'Export PNG';
      btn.disabled = false;
    };
    img.onerror = () => {
      btn.textContent = 'Export PNG';
      btn.disabled = false;
      alert('Export failed — try right-click → Save As on the page.');
    };
    img.src = url;
  } catch (e) {
    console.error(e);
    btn.textContent = 'Export PNG';
    btn.disabled = false;
  }
}
</script>

